Action.ExecScriptExpression:
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Triggernometry.Core;
using Triggernometry.Core.Scripting;
using Triggernometry.FFXIV;
using Triggernometry.PluginBridges;
using Triggernometry.PluginBridges.BridgeNamazu;
using Triggernometry.PluginBridges.BridgeNamazu.Modules;

/// <summary>Triggernometry script entry point for the Crescent correction checker.</summary>
public static class SpecialAttributeCheckEntry
{
    public const string CallbackName = "SpecialAttributeCheck";

    /// <summary>Replaces the previous callback instance and registers a fresh controller.</summary>
    public static void Register(ScriptContextHelper helpers)
    {
        RealPlugin.Instance.InvokeNamedCallback(CallbackName, "__dispose");
        var controller = new SpecialAttributeCheckController(helpers);
        RealPlugin.Instance.RegisterNamedCallback(
            CallbackName,
            new Action<object, string>(SpecialAttributeCheckController.Dispatch),
            controller,
            false,
            "SpecialAttributeCheck Trigger script");
        controller.Log("具名回调已注册。使用 /e cb SpecialAttributeCheck help 查看命令。");
    }
}

internal sealed class SpecialAttributeCheckController
{
    private readonly object operationLock = new object();
    private readonly ScriptContextHelper helpers;
    private readonly SpecialAttributeRuntime runtime;
    private CancellationTokenSource operationCancellation;
    private Task operationTask;
    private int disposed;

    public SpecialAttributeCheckController(ScriptContextHelper scriptHelpers)
    {
        helpers = scriptHelpers ?? throw new ArgumentNullException("scriptHelpers");
        runtime = new SpecialAttributeRuntime(Log, Echo);
    }

    public static void Dispatch(object state, string input)
    {
        var controller = state as SpecialAttributeCheckController;
        if (controller == null)
            return;
        controller.Handle(input ?? string.Empty);
    }

    public void Log(string message)
    {
        helpers.Log(RealPlugin.DebugLevelEnum.Info, "[补正检测] " + message);
    }

    private void Handle(string input)
    {
        SpecialAttributeCommand command;
        string error;
        if (!SpecialAttributeCommandParser.TryParse(input, out command, out error))
        {
            Echo(error);
            return;
        }

        if (command.Kind == SpecialAttributeCommandKind.Dispose)
        {
            Interlocked.Exchange(ref disposed, 1);
            Cancel(false, true);
            return;
        }
        if (command.Kind == SpecialAttributeCommandKind.Cancel)
        {
            Cancel(true, false);
            return;
        }

        StartOperation(command);
    }

    private void StartOperation(SpecialAttributeCommand command)
    {
        if (Volatile.Read(ref disposed) != 0)
            return;

        CancellationTokenSource cancellation;
        lock (operationLock)
        {
            if (operationCancellation != null)
            {
                Echo("已有查询正在执行；使用 cancel 取消。");
                return;
            }
            cancellation = new CancellationTokenSource();
            operationCancellation = cancellation;
            operationTask = Task.Run(() => RunOperationAsync(command, cancellation));
        }
    }

    private async Task RunOperationAsync(
        SpecialAttributeCommand command,
        CancellationTokenSource cancellation)
    {
        IDisposable lease = null;
        try
        {
            lease = SpecialAttributeGlobalLease.Acquire(cancellation.Token);
            await ExecuteAsync(command, cancellation.Token).ConfigureAwait(false);
        }
        catch (OperationCanceledException)
        {
            Echo("查询已取消。");
        }
        catch (Exception ex)
        {
            Log("查询失败：" + ex);
            Echo("查询失败：" + ex.Message);
        }
        finally
        {
            if (lease != null)
                lease.Dispose();
            lock (operationLock)
            {
                if (ReferenceEquals(operationCancellation, cancellation))
                {
                    operationCancellation.Dispose();
                    operationCancellation = null;
                    operationTask = null;
                }
            }
        }
    }

    private async Task ExecuteAsync(SpecialAttributeCommand command, CancellationToken cancellation)
    {
        switch (command.Kind)
        {
            case SpecialAttributeCommandKind.Help:
                await ShowHelpAsync(cancellation).ConfigureAwait(false);
                break;
            case SpecialAttributeCommandKind.Probe:
                await ProbeAsync(cancellation).ConfigureAwait(false);
                break;
            case SpecialAttributeCommandKind.Party:
            case SpecialAttributeCommandKind.Nearby:
            case SpecialAttributeCommandKind.Target:
                await ScanAsync(command, cancellation).ConfigureAwait(false);
                break;
            default:
                throw new InvalidOperationException("不支持的命令。");
        }
    }

    private async Task ShowHelpAsync(CancellationToken cancellation)
    {
        var lines = new[]
        {
            "命令：party / nearby / target [total|split] [debug]",
            "诊断：probe 或查询后加 debug；取消：cancel。",
            "示例：/e cb SpecialAttributeCheck nearby debug"
        };
        await EchoLinesAsync(lines, cancellation).ConfigureAwait(false);
    }

    private async Task ProbeAsync(CancellationToken cancellation)
    {
        var me = runtime.CaptureSelf();
        var entities = runtime.CapturePlayers();
        Echo(string.Format(
            "探针：区域={0} 玩家数={1} 自身={2}({3:X8}) x={4}",
            runtime.ZoneId,
            entities.Count,
            me == null ? "?" : me.Name,
            me == null ? 0u : me.EntityId,
            me == null ? 0 : me.X));

        runtime.Inventory.EnsureReady();
        var localItems = runtime.Inventory.ReadLocalEquippedItems();
        Echo("探针：本地装备非空槽=" + localItems.Count);

        if (me == null || me.TargetId == 0)
        {
            Echo("探针：当前没有目标，远端 13 槽未测试。");
            return;
        }

        var target = entities.FirstOrDefault(item => item.EntityId == me.TargetId);
        if (target == null)
        {
            Echo("探针：当前目标不在 ACT 玩家实体表中。");
            return;
        }

        var targetItems = await runtime.Inventory
            .ReadInspectedItemsAsync(target, cancellation, true, "probe")
            .ConfigureAwait(false);
        Echo(string.Format(
            "探针：目标={0}({1:X8}) x={2} 装备非空槽={3}/13",
            target.Name,
            target.EntityId,
            target.X,
            targetItems.Count));
    }

    private async Task ScanAsync(SpecialAttributeCommand command, CancellationToken cancellation)
    {
        if (!SpecialAttributeData.IsCrescentTerritory(runtime.ZoneId))
        {
            Echo("当前不在新月岛南部或北部，已拒绝查询。");
            return;
        }

        var targets = runtime.SelectTargets(command.Kind);
        if (targets.Count == 0)
        {
            Echo(command.Kind == SpecialAttributeCommandKind.Target
                ? "请先选中一名玩家。"
                : "没有找到可检测的玩家。");
            return;
        }

        runtime.Inventory.EnsureReady();
        if (command.Verbose)
            Echo("诊断模式已启用；仅在状态变化或每 2 秒心跳时输出。");
        Echo("开始检测，共 " + targets.Count + " 人。");
        var results = new List<SpecialAttributeResult>(targets.Count);
        for (var index = 0; index < targets.Count; index++)
        {
            cancellation.ThrowIfCancellationRequested();
            var result = await ScanTargetAsync(
                command,
                targets[index],
                index + 1,
                targets.Count,
                cancellation).ConfigureAwait(false);
            if (result != null)
                results.Add(result);

            var completed = index + 1;
            if (targets.Count <= 8 || completed == targets.Count || completed % 5 == 0)
                Echo(string.Format("检测中 {0}/{1} ...", completed, targets.Count));
        }

        SpecialAttributeLogic.SortResults(results);
        var output = results.Select(item => item.DisplayLine).ToArray();
        await EchoLinesAsync(output, cancellation).ConfigureAwait(false);
        Echo("检测完成，共 " + results.Count + " 人。");
    }

    private async Task<SpecialAttributeResult> ScanTargetAsync(
        SpecialAttributeCommand command,
        SpecialAttributePlayer target,
        int position,
        int total,
        CancellationToken cancellation)
    {
        try
        {
            Func<SpecialAttributePlayer> refreshTarget = null;
            if (command.Kind == SpecialAttributeCommandKind.Nearby && !target.IsLocal)
                refreshTarget = () => runtime.FindNearbyTarget(target.EntityId);
            IReadOnlyList<uint> itemIds = target.IsLocal
                ? runtime.Inventory.ReadLocalEquippedItems()
                : await runtime.Inventory.ReadInspectedItemsAsync(
                    target,
                    cancellation,
                    command.Verbose,
                    position + "/" + total,
                    refreshTarget).ConfigureAwait(false);
            if (command.Verbose && target.IsLocal)
            {
                Echo(string.Format(
                    "诊断 {0}/{1} {2}({3:X8})：本地装备槽位={4}",
                    position,
                    total,
                    target.Name,
                    target.EntityId,
                    itemIds.Count));
            }
            return SpecialAttributeLogic.CreateResult(
                target, itemIds, command.DisplayMode);
        }
        catch (OperationCanceledException)
        {
            throw;
        }
        catch (SpecialAttributeTargetUnavailableException ex)
        {
            Echo(string.Format(
                "跳过 {0}/{1} {2}({3:X8})：{4}",
                position,
                total,
                target.Name,
                target.EntityId,
                ex.Message));
            return null;
        }
        catch (Exception ex)
        {
            Log(string.Format(
                "读取 {0}({1:X8}) 装备失败：{2}",
                target.Name,
                target.EntityId,
                ex.Message));
            if (command.Kind == SpecialAttributeCommandKind.Target)
                Echo("目标装备读取失败：" + ex.Message);
            return SpecialAttributeLogic.CreateUnknownResult(target, command.DisplayMode);
        }
    }

    private void Cancel(bool announce, bool waitForExit)
    {
        CancellationTokenSource cancellation;
        Task task;
        lock (operationLock)
        {
            cancellation = operationCancellation;
            task = operationTask;
            if (cancellation != null)
                cancellation.Cancel();
        }
        if (waitForExit && task != null)
        {
            try
            {
                task.Wait(TimeSpan.FromSeconds(2));
            }
            catch (AggregateException ex)
            {
                if (ex.InnerExceptions.Any(item => !(item is OperationCanceledException)))
                    Log("等待旧查询退出时发生异常：" + ex.Flatten());
            }
        }
        if (announce)
            Echo(cancellation == null ? "当前没有正在执行的查询。" : "正在取消查询...");
    }

    private async Task EchoLinesAsync(IEnumerable<string> lines, CancellationToken cancellation)
    {
        foreach (var line in lines)
        {
            cancellation.ThrowIfCancellationRequested();
            Echo(line);
            await Task.Delay(150, cancellation).ConfigureAwait(false);
        }
    }

    private void Echo(string message)
    {
        if (Volatile.Read(ref disposed) != 0)
            return;

        var text = (message ?? string.Empty)
            .Replace('\r', ' ')
            .Replace('\n', ' ')
            .Trim();
        if (text.Length > 180)
            text = text.Substring(0, 177) + "...";
        Log(text);
        try
        {
            RealPlugin.Instance.InvokeNamedCallback("command", "/e [补正检测] " + text);
        }
        catch (Exception ex)
        {
            Log("默语输出失败：" + ex.Message);
        }
    }
}

internal enum SpecialAttributeCommandKind
{
    Help,
    Probe,
    Party,
    Nearby,
    Target,
    Cancel,
    Dispose
}

internal enum SpecialAttributeDisplayMode
{
    Total,
    Split
}

internal sealed class SpecialAttributeCommand
{
    public SpecialAttributeCommandKind Kind;
    public SpecialAttributeDisplayMode DisplayMode;
    public bool Verbose;
}

internal static class SpecialAttributeCommandParser
{
    public static bool TryParse(string input, out SpecialAttributeCommand command, out string error)
    {
        command = null;
        error = string.Empty;
        var parts = (input ?? string.Empty)
            .Split(new[] { ' ', '\t', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
        if (parts.Length == 0)
        {
            command = NewCommand(SpecialAttributeCommandKind.Help);
            return true;
        }

        var name = parts[0].ToLowerInvariant();
        if (name == "__dispose")
            return Finish(NewCommand(SpecialAttributeCommandKind.Dispose), out command);
        if (name == "help" || name == "?")
            return Finish(NewCommand(SpecialAttributeCommandKind.Help), out command);
        if (name == "probe")
            return Finish(NewCommand(SpecialAttributeCommandKind.Probe), out command);
        if (name == "cancel")
            return Finish(NewCommand(SpecialAttributeCommandKind.Cancel), out command);

        SpecialAttributeCommandKind kind;
        if (name == "party")
            kind = SpecialAttributeCommandKind.Party;
        else if (name == "nearby")
            kind = SpecialAttributeCommandKind.Nearby;
        else if (name == "target")
            kind = SpecialAttributeCommandKind.Target;
        else
        {
            error = "未知命令：" + parts[0] + "。使用 help 查看命令。";
            return false;
        }

        var parsed = NewCommand(kind);
        if (!TryParseScanOptions(parts, name, parsed, out error))
            return false;
        command = parsed;
        return true;
    }

    private static bool TryParseScanOptions(
        string[] parts,
        string name,
        SpecialAttributeCommand command,
        out string error)
    {
        error = string.Empty;
        if (parts.Length > 3)
        {
            error = "参数过多。格式为 " + name + " [total|split] [debug]。";
            return false;
        }
        var displayModeSeen = false;
        for (var index = 1; index < parts.Length; index++)
        {
            var option = parts[index].ToLowerInvariant();
            if (option == "debug")
            {
                if (command.Verbose)
                {
                    error = "debug 参数重复。";
                    return false;
                }
                command.Verbose = true;
                continue;
            }
            if (option == "total" || option == "split")
            {
                if (displayModeSeen)
                {
                    error = "显示模式参数重复。";
                    return false;
                }
                command.DisplayMode = option == "split"
                    ? SpecialAttributeDisplayMode.Split
                    : SpecialAttributeDisplayMode.Total;
                displayModeSeen = true;
                continue;
            }
            error = "未知参数：" + parts[index] + "。仅支持 total、split 或 debug。";
            return false;
        }
        return true;
    }

    private static SpecialAttributeCommand NewCommand(SpecialAttributeCommandKind kind)
    {
        return new SpecialAttributeCommand
        {
            Kind = kind,
            DisplayMode = SpecialAttributeDisplayMode.Total,
            Verbose = false
        };
    }

    private static bool Finish(SpecialAttributeCommand value, out SpecialAttributeCommand command)
    {
        command = value;
        return true;
    }
}

internal sealed class SpecialAttributePlayer
{
    public uint EntityId;
    public string Name;
    public int JobId;
    public string JobName;
    public float XPosition;
    public float YPosition;
    public float ZPosition;
    public int X;
    public bool IsLocal;
    public bool InParty;
    public int PartyIndex;
    public uint TargetId;
    public IntPtr Address;
}

internal sealed class SpecialAttributeResult
{
    public string Name;
    public string JobName;
    public int X;
    public int Y;
    public bool IsYUnknown;
    public string CorrectionText;

    public int? Total
    {
        get { return IsYUnknown ? (int?)null : (2 * X) + Y; }
    }

    public string DisplayLine
    {
        get { return JobName + " " + Name + " " + CorrectionText; }
    }
}

internal static class SpecialAttributeLogic
{
    public static int SumStatusStacks(IEnumerable<KeyValuePair<ushort, ushort>> statuses)
    {
        return statuses
            .Where(item => item.Key == SpecialAttributeData.SupportJobMasterStatusId)
            .Sum(item => (int)item.Value);
    }

    public static List<SpecialAttributePlayer> SelectTargets(
        SpecialAttributeCommandKind kind,
        IList<SpecialAttributePlayer> players,
        SpecialAttributePlayer local)
    {
        if (local == null)
            return new List<SpecialAttributePlayer>();
        if (kind == SpecialAttributeCommandKind.Target)
        {
            var target = players.FirstOrDefault(item => item.EntityId == local.TargetId);
            return target == null
                ? new List<SpecialAttributePlayer>()
                : new List<SpecialAttributePlayer> { target };
        }
        if (kind == SpecialAttributeCommandKind.Party)
        {
            return players
                .Where(item => item.InParty || item.EntityId == local.EntityId)
                .GroupBy(item => item.EntityId)
                .Select(group => group.First())
                .ToList();
        }
        if (kind == SpecialAttributeCommandKind.Nearby)
        {
            return players
                .Where(item => IsWithinNearbyRange(item, local))
                .Take(SpecialAttributeData.MaxNearbyPlayers)
                .ToList();
        }
        return new List<SpecialAttributePlayer>();
    }

    public static int SumSpecialCorrection(IEnumerable<uint> itemIds)
    {
        var worn = new HashSet<uint>();
        var result = 0;
        foreach (var itemId in itemIds)
        {
            if (itemId == 0)
                continue;
            worn.Add(itemId);
            int correction;
            if (SpecialAttributeData.EquipmentCorrection.TryGetValue(itemId, out correction))
                result += correction;
        }
        if (SpecialAttributeData.PowerSetItems.All(worn.Contains))
            result += SpecialAttributeData.SetBonusCorrection;
        if (SpecialAttributeData.MagicSetItems.All(worn.Contains))
            result += SpecialAttributeData.SetBonusCorrection;
        return result;
    }

    public static SpecialAttributeResult CreateResult(
        SpecialAttributePlayer player,
        IEnumerable<uint> itemIds,
        SpecialAttributeDisplayMode mode)
    {
        var y = SumSpecialCorrection(itemIds);
        return new SpecialAttributeResult
        {
            Name = player.Name,
            JobName = player.JobName,
            X = player.X,
            Y = y,
            IsYUnknown = false,
            CorrectionText = mode == SpecialAttributeDisplayMode.Total
                ? ((2 * player.X) + y).ToString()
                : player.X + "★+" + y
        };
    }

    public static SpecialAttributeResult CreateUnknownResult(
        SpecialAttributePlayer player,
        SpecialAttributeDisplayMode mode)
    {
        return new SpecialAttributeResult
        {
            Name = player.Name,
            JobName = player.JobName,
            X = player.X,
            Y = 0,
            IsYUnknown = true,
            CorrectionText = mode == SpecialAttributeDisplayMode.Total
                ? "?"
                : player.X + "★+?"
        };
    }

    public static void SortResults(List<SpecialAttributeResult> results)
    {
        results.Sort(delegate(SpecialAttributeResult left, SpecialAttributeResult right)
        {
            return (right.Total ?? int.MinValue)
                .CompareTo(left.Total ?? int.MinValue);
        });
    }

    public static bool IsWithinNearbyRange(
        SpecialAttributePlayer target,
        SpecialAttributePlayer local)
    {
        return target != null
            && local != null
            && Distance(target, local) <= SpecialAttributeData.NearbyScanRadius;
    }

    private static double Distance(SpecialAttributePlayer left, SpecialAttributePlayer right)
    {
        var x = left.XPosition - right.XPosition;
        var y = left.YPosition - right.YPosition;
        var z = left.ZPosition - right.ZPosition;
        return Math.Sqrt((x * x) + (y * y) + (z * z));
    }
}

internal static class SpecialAttributeGlobalLease
{
    private const string SemaphoreName = "Local\\Triggernometry.SpecialAttributeCheck.Scan";

    public static IDisposable Acquire(CancellationToken cancellation)
    {
        var semaphore = new Semaphore(1, 1, SemaphoreName);
        var selected = WaitHandle.WaitAny(new WaitHandle[] { semaphore, cancellation.WaitHandle });
        if (selected == 1)
        {
            semaphore.Dispose();
            throw new OperationCanceledException(cancellation);
        }
        if (cancellation.IsCancellationRequested)
        {
            semaphore.Release();
            semaphore.Dispose();
            throw new OperationCanceledException(cancellation);
        }
        return new Lease(semaphore);
    }

    private sealed class Lease : IDisposable
    {
        private Semaphore semaphore;

        public Lease(Semaphore value)
        {
            semaphore = value;
        }

        public void Dispose()
        {
            var value = Interlocked.Exchange(ref semaphore, null);
            if (value == null)
                return;
            value.Release();
            value.Dispose();
        }
    }
}

internal sealed class SpecialAttributeElapsedTimer
{
    private readonly int startedAt;

    private SpecialAttributeElapsedTimer()
    {
        startedAt = Environment.TickCount;
    }

    public long ElapsedMilliseconds
    {
        get { return ElapsedBetween(startedAt, Environment.TickCount); }
    }

    public static SpecialAttributeElapsedTimer StartNew()
    {
        return new SpecialAttributeElapsedTimer();
    }

    public static long ElapsedBetween(int startedAt, int current)
    {
        return unchecked((uint)(current - startedAt));
    }
}

internal static class SpecialAttributeInspectPolicy
{
    public const uint InvalidEntityId = 0xE0000000;
    public const int MaxAttempts = 2;
    public const int RetryDelayMilliseconds = 1000;
    public const int InspectTimeoutMilliseconds = 6000;
    public const int PollDelayMilliseconds = 100;
    public const int ReadySettleMilliseconds = 300;
    public const int CloseSettleMilliseconds = 300;
    public const int WindowCloseTimeoutMilliseconds = 2000;

    public static bool CanAcceptInspectSource(
        string source,
        uint expectedEntityId,
        uint currentEntityId,
        uint status,
        bool inspectAddonOpen)
    {
        if (source == "Examine")
            return inspectAddonOpen;
        return source == "AgentInspect"
            && IsAgentInspectReady(expectedEntityId, currentEntityId, status);
    }

    public static bool IsAgentInspectReady(
        uint expectedEntityId,
        uint currentEntityId,
        uint status)
    {
        return currentEntityId == expectedEntityId && status == 2;
    }

    public static bool OwnsInspectRequest(uint expectedEntityId, uint currentEntityId)
    {
        return currentEntityId == expectedEntityId
            || currentEntityId == 0
            || currentEntityId == InvalidEntityId;
    }

    public static bool IsStableMatch(
        string source,
        uint expectedEntityId,
        uint currentEntityId,
        uint status,
        bool inspectAddonOpen,
        IReadOnlyList<uint> first,
        IReadOnlyList<uint> second)
    {
        return CanAcceptInspectSource(
                source, expectedEntityId, currentEntityId, status, inspectAddonOpen)
            && first != null
            && second != null
            && first.SequenceEqual(second)
            && first.Any(item => item != 0);
    }

    public static IReadOnlyList<uint> SelectPreferredItems(
        IReadOnlyList<uint> examineItems,
        IReadOnlyList<uint> agentItems,
        bool agentReady,
        out string source)
    {
        var examineNonZero = (examineItems ?? new uint[0])
            .Where(item => item != 0)
            .ToArray();
        var agentNonZero = (agentItems ?? new uint[0])
            .Where(item => item != 0)
            .ToArray();
        if (examineNonZero.Length > 0
            && agentReady
            && agentNonZero.Length > 0
            && !examineNonZero.SequenceEqual(agentNonZero))
        {
            source = "Mismatch";
            return new uint[0];
        }
        if (examineNonZero.Length > 0)
        {
            source = "Examine";
            return examineItems;
        }
        if (!agentReady)
        {
            source = "无";
            return new uint[0];
        }
        source = "AgentInspect";
        return agentItems ?? new uint[0];
    }
}

internal sealed class SpecialAttributeInspectAttemptResult
{
    public SpecialAttributeInspectAttemptResult(
        IReadOnlyList<uint> items,
        string diagnostic)
    {
        Items = items;
        Diagnostic = diagnostic ?? string.Empty;
    }

    public IReadOnlyList<uint> Items { get; private set; }
    public string Diagnostic { get; private set; }
}

internal sealed class SpecialAttributeTargetUnavailableException : Exception
{
    public SpecialAttributeTargetUnavailableException(string message)
        : base(message)
    {
    }
}

internal sealed class SpecialAttributeRuntime
{
    private readonly Action<string> log;

    public SpecialAttributeRuntime(Action<string> logger, Action<string> diagnostic)
    {
        log = logger ?? delegate { };
        Inventory = new SpecialAttributeInventoryReader(log, diagnostic);
    }

    public SpecialAttributeInventoryReader Inventory { get; private set; }

    public uint ZoneId
    {
        get { return BridgeFFXIV.ZoneID; }
    }

    public SpecialAttributePlayer CaptureSelf()
    {
        var entity = Entity.GetMyself();
        return entity == null || !entity.Exist ? null : Capture(entity, entity.ID);
    }

    public List<SpecialAttributePlayer> CapturePlayers()
    {
        var myself = Entity.GetMyself();
        var localId = myself == null || !myself.Exist ? 0u : myself.ID;
        return Entity.GetEntities(item => item.Exist && item.Type == EntityType.Pc)
            .Select(item => Capture(item, localId))
            .Where(item => item != null)
            .GroupBy(item => item.EntityId)
            .Select(group => group.First())
            .ToList();
    }

    public List<SpecialAttributePlayer> SelectTargets(SpecialAttributeCommandKind kind)
    {
        var local = CaptureSelf();
        var players = CapturePlayers();
        if (kind == SpecialAttributeCommandKind.Party)
            players = MergePartyFallback(players, Inventory.ReadPartyMembers(), local);
        return SpecialAttributeLogic.SelectTargets(kind, players, local);
    }

    public SpecialAttributePlayer FindNearbyTarget(uint entityId)
    {
        var local = CaptureSelf();
        if (local == null)
            return null;
        var target = CapturePlayers()
            .FirstOrDefault(item => item.EntityId == entityId);
        return SpecialAttributeLogic.IsWithinNearbyRange(target, local)
            ? target
            : null;
    }

    private List<SpecialAttributePlayer> MergePartyFallback(
        List<SpecialAttributePlayer> entities,
        IReadOnlyList<SpecialAttributePlayer> party,
        SpecialAttributePlayer local)
    {
        var byId = entities.ToDictionary(item => item.EntityId);
        foreach (var fallback in party)
        {
            SpecialAttributePlayer existing;
            if (byId.TryGetValue(fallback.EntityId, out existing))
            {
                existing.InParty = true;
                existing.PartyIndex = fallback.PartyIndex;
            }
            else
            {
                fallback.IsLocal = local != null && fallback.EntityId == local.EntityId;
                entities.Add(fallback);
                byId[fallback.EntityId] = fallback;
            }
        }
        if (local != null && !byId.ContainsKey(local.EntityId))
            entities.Add(local);
        return entities;
    }

    private SpecialAttributePlayer Capture(Entity entity, uint localId)
    {
        try
        {
            var statuses = (entity.Statuses ?? new List<Status>())
                .Select(item => new KeyValuePair<ushort, ushort>(item.StatusID, item.Stack));
            var jobId = entity.Job == null ? 0 : entity.Job.JobID;
            return new SpecialAttributePlayer
            {
                EntityId = entity.ID,
                Name = string.IsNullOrWhiteSpace(entity.Name) ? entity.HexID : entity.Name,
                JobId = jobId,
                JobName = SpecialAttributeData.GetJobName(jobId),
                XPosition = entity.PosX,
                YPosition = entity.PosY,
                ZPosition = entity.PosZ,
                X = SpecialAttributeLogic.SumStatusStacks(statuses),
                IsLocal = entity.ID == localId,
                InParty = entity.InParty,
                TargetId = entity.TargetID,
                Address = entity.Address
            };
        }
        catch (Exception ex)
        {
            log(string.Format("复制实体 {0:X8} 数据失败：{1}", entity.ID, ex.Message));
            return null;
        }
    }
}

internal sealed class SpecialAttributeInventoryReader
{
    private const int InspectAgentId = 51;
    private const int AgentArrayOffset = 0x20;
    private const int AgentModuleUiModuleOffset = 0x08;
    private const int GetAgentModuleVtableIndex = 37;
    private const int FrameworkUiModuleOffset75 = 0x2B68;
    private const int InspectCurrentEntityOffset = 0x34;
    private const int InspectItemsOffset = 0x2A8;
    private const int InspectItemSize = 0x1C;
    private const int InspectStatusOffset = 0x608;
    private const int InspectSlotCount = 13;
    private const int InventoryContainersOffset = 0x1E08;
    private const int InventoryContainerSize = 0x20;
    private const int InventoryItemsOffset = 0x08;
    private const int InventoryTypeOffset = 0x10;
    private const int InventorySizeOffset = 0x14;
    private const int InventoryLoadedOffset = 0x18;
    private const int InventoryItemSize = 0x48;
    private const int InventoryItemIdOffset = 0x10;
    private const int EquippedItemsType = 1000;
    private const int ExamineItemsType = 2009;
    private const int MaxInventoryContainers = 160;
    private const int GroupMainOffset = 0x20;
    private const int GroupMemberCountOffset = 0x7FDC;
    private const int PartyMemberSize = 0x490;
    private const int PartyMemberPositionOffset = 0x3E0;
    private const int PartyMemberEntityIdOffset = 0x400;
    private const int PartyMemberNameOffset = 0x41C;
    private const int PartyMemberNameLength = 64;
    private const int PartyMemberJobOffset = 0x469;
    private const int StatusArrayOffset = 0x08;
    private const int StatusSize = 0x10;
    private const int StatusCount = 60;
    private const int AtkStageRaptureUnitManagerOffset = 0x20;
    private const int AllLoadedUnitsListOffset = 0x6900;
    private const int AtkUnitListEntriesOffset = 0x08;
    private const int AtkUnitListCountOffset = 0x808;
    private const int MaxLoadedAtkUnits = 256;
    private const int AtkUnitNameOffset = 0x08;
    private const int AtkUnitNameLength = 32;
    private const int AtkUnitCloseVtableIndex = 4;
    private const string CharacterInspectAddonName = "CharacterInspect";

    private readonly object initializationLock = new object();
    private readonly Action<string> diagnostic;
    private readonly Action<string> log;
    private SpecialAttributeMemory memory;
    private NamazuPlugin plugin;
    private EntityModule entityModule;
    private IntPtr inspectAgent;
    private IntPtr inventoryManager;
    private IntPtr examineItemsContainer;
    private bool examineContainerLookupAttempted;
    private IntPtr groupManager;
    private IntPtr raptureAtkUnitManager;
    private int processId;

    public SpecialAttributeInventoryReader(
        Action<string> logger,
        Action<string> diagnosticOutput)
    {
        log = logger ?? delegate { };
        diagnostic = diagnosticOutput ?? delegate { };
    }

    public void EnsureReady()
    {
        lock (initializationLock)
        {
            var currentPlugin = BridgeNamazu.NamazuPlugin;
            if (currentPlugin == null || !currentPlugin.IsReady)
                throw new InvalidOperationException("PostNamazu 未就绪，无法访问游戏进程。");
            if (memory != null && processId == currentPlugin.Memory.Process.Id)
                return;
            Initialize(currentPlugin);
        }
    }

    public IReadOnlyList<uint> ReadLocalEquippedItems()
    {
        EnsureReady();
        var container = FindInventoryContainer(EquippedItemsType);
        if (container == IntPtr.Zero)
            throw new InvalidOperationException("未找到 EquippedItems 容器；当前布局可能已过期。");
        return ReadInventoryContainer(container);
    }

    public IReadOnlyList<SpecialAttributePlayer> ReadPartyMembers()
    {
        EnsureReady();
        var group = groupManager + GroupMainOffset;
        var count = memory.Read<byte>(group + GroupMemberCountOffset);
        if (count > 8)
            throw new InvalidOperationException("GroupManager 队员数量无效；当前布局可能已过期。");
        var result = new List<SpecialAttributePlayer>(count);
        for (var index = 0; index < count; index++)
        {
            var member = group + (index * PartyMemberSize);
            var entityId = memory.Read<uint>(member + PartyMemberEntityIdOffset);
            if (entityId == 0 || entityId == 0xE0000000)
                continue;
            var jobId = memory.Read<byte>(member + PartyMemberJobOffset);
            result.Add(new SpecialAttributePlayer
            {
                EntityId = entityId,
                Name = ReadUtf8(member + PartyMemberNameOffset, PartyMemberNameLength),
                JobId = jobId,
                JobName = SpecialAttributeData.GetJobName(jobId),
                XPosition = memory.Read<float>(member + PartyMemberPositionOffset),
                YPosition = memory.Read<float>(member + PartyMemberPositionOffset + 4),
                ZPosition = memory.Read<float>(member + PartyMemberPositionOffset + 8),
                X = ReadSupportJobStacks(member),
                InParty = true,
                PartyIndex = index + 1,
                Address = IntPtr.Zero
            });
        }
        return result;
    }

    public async Task<IReadOnlyList<uint>> ReadInspectedItemsAsync(
        SpecialAttributePlayer target,
        CancellationToken cancellation,
        bool verbose,
        string traceContext,
        Func<SpecialAttributePlayer> refreshTarget = null)
    {
        EnsureReady();
        ValidateInspectTarget(target);

        IntPtr hardTargetAddress;
        IntPtr softTargetAddress;
        IntPtr originalHard;
        IntPtr originalSoft;
        CaptureTargetPointers(
            out hardTargetAddress,
            out softTargetAddress,
            out originalHard,
            out originalSoft);
        var ownedTargetAddresses = new HashSet<IntPtr>();
        Exception operationError = null;
        var totalTimer = SpecialAttributeElapsedTimer.StartNew();
        var targetLabel = FormatInspectTargetLabel(traceContext, target);
        try
        {
            return await ReadInspectedItemsWithRetriesAsync(
                target,
                hardTargetAddress,
                targetLabel,
                totalTimer,
                verbose,
                ownedTargetAddresses,
                refreshTarget,
                cancellation).ConfigureAwait(false);
        }
        catch (Exception ex)
        {
            operationError = ex;
            throw;
        }
        finally
        {
            try
            {
                RestoreTargetsOrThrow(
                    hardTargetAddress,
                    softTargetAddress,
                    originalHard,
                    originalSoft,
                    ownedTargetAddresses,
                    operationError);
            }
            finally
            {
                Trace(verbose, targetLabel
                    + "：结束，累计=" + totalTimer.ElapsedMilliseconds + "ms");
            }
        }
    }

    private static void ValidateInspectTarget(SpecialAttributePlayer target)
    {
        if (target == null || target.EntityId == 0)
            throw new InvalidOperationException("查看目标缺少有效实体 ID。");
        if (target.Address == IntPtr.Zero && target.PartyIndex <= 0)
            throw new InvalidOperationException("查看目标既没有实体地址，也没有小队序号。");
    }

    private static string FormatInspectTargetLabel(
        string traceContext,
        SpecialAttributePlayer target)
    {
        return string.Format(
            "{0} {1}({2:X8})",
            traceContext,
            target.Name,
            target.EntityId);
    }

    private void CaptureTargetPointers(
        out IntPtr hardTargetAddress,
        out IntPtr softTargetAddress,
        out IntPtr originalHard,
        out IntPtr originalSoft)
    {
        var targetSystem = entityModule.TargetSystemPtr;
        RequirePointer(targetSystem, "TargetSystem");
        var hardOffset = entityModule.HardTargetOffset();
        if (hardOffset < 0 || hardOffset > 0x1000)
            throw new InvalidOperationException("TargetSystem 目标偏移无效；当前布局可能已过期。");
        hardTargetAddress = AddOffset(
            targetSystem, hardOffset, "TargetSystem.HardTarget");
        softTargetAddress = AddOffset(
            targetSystem, hardOffset + 8, "TargetSystem.SoftTarget");
        originalHard = memory.Read<IntPtr>(hardTargetAddress);
        originalSoft = memory.Read<IntPtr>(softTargetAddress);
    }

    private void RestoreTargetsOrThrow(
        IntPtr hardTargetAddress,
        IntPtr softTargetAddress,
        IntPtr originalHard,
        IntPtr originalSoft,
        ICollection<IntPtr> ownedTargetAddresses,
        Exception operationError)
    {
        var restoreErrors = new List<Exception>();
        AddError(restoreErrors, TryRestoreTarget(
            hardTargetAddress,
            ownedTargetAddresses,
            originalHard,
            "硬目标"));
        AddError(restoreErrors, TryRestoreTarget(
            softTargetAddress,
            ownedTargetAddresses,
            originalSoft,
            "软目标"));
        if (restoreErrors.Count == 0)
            return;
        if (operationError != null)
            restoreErrors.Insert(0, operationError);
        throw new AggregateException("查看装备后恢复玩家目标失败。", restoreErrors);
    }

    private async Task<IReadOnlyList<uint>> ReadInspectedItemsWithRetriesAsync(
        SpecialAttributePlayer target,
        IntPtr hardTargetAddress,
        string targetLabel,
        SpecialAttributeElapsedTimer totalTimer,
        bool verbose,
        ICollection<IntPtr> ownedTargetAddresses,
        Func<SpecialAttributePlayer> refreshTarget,
        CancellationToken cancellation)
    {
        var lastDiagnostic = "尚未观察到 AgentInspect 状态";
        for (var attempt = 1; attempt <= SpecialAttributeInspectPolicy.MaxAttempts; attempt++)
        {
            cancellation.ThrowIfCancellationRequested();
            var attemptLabel = string.Format(
                "{0} 尝试 {1}/{2}",
                targetLabel,
                attempt,
                SpecialAttributeInspectPolicy.MaxAttempts);
            Trace(verbose, attemptLabel + "：开始");
            var result = await TryInspectAsync(
                target,
                hardTargetAddress,
                attemptLabel,
                verbose,
                ownedTargetAddresses,
                refreshTarget,
                cancellation).ConfigureAwait(false);
            lastDiagnostic = result.Diagnostic;
            if (result.Items != null)
            {
                Trace(verbose, string.Format(
                    "{0}：成功，槽位={1}，累计={2}ms",
                    attemptLabel,
                    result.Items.Count,
                    totalTimer.ElapsedMilliseconds));
                return result.Items;
            }
            if (attempt < SpecialAttributeInspectPolicy.MaxAttempts)
            {
                Trace(verbose, attemptLabel
                    + "：未取得数据，1 秒后重试；" + lastDiagnostic);
                await Task.Delay(
                    SpecialAttributeInspectPolicy.RetryDelayMilliseconds,
                    cancellation).ConfigureAwait(false);
            }
        }
        throw new TimeoutException(
            "2 次查看后未得到装备数据；最后状态：" + lastDiagnostic);
    }

    private void Initialize(NamazuPlugin currentPlugin)
    {
        if (!BridgeNamazu.Modules.ContainsKey(typeof(EntityModule)))
            BridgeNamazu.InitializeModules();
        plugin = currentPlugin;
        entityModule = BridgeNamazu.GetModule<EntityModule>();
        if (entityModule.TargetSystemPtr == IntPtr.Zero)
            entityModule.Scan();
        memory = new SpecialAttributeMemory(plugin.Memory);
        processId = plugin.Memory.Process.Id;

        var scanner = plugin.SigScanner;
        var frameworkStatic = scanner.ScanText(
            "48 8B 1D * * * * 8B 7C 24",
            "SpecialAttributeCheck.Framework");
        var framework = memory.Read<IntPtr>(frameworkStatic);
        RequirePointer(framework, "Framework");

        var getUiModule = scanner.ScanText(
            "E8 * * * * 80 7B 1D 01",
            "SpecialAttributeCheck.GetUIModule");
        RequirePointer(getUiModule, "Framework.GetUIModule");
        IntPtr uiModule;
        try
        {
            uiModule = plugin.Call<IntPtr>(getUiModule, framework);
        }
        catch (Exception ex)
        {
            log("调用 Framework.GetUIModule 失败，尝试直接字段回退：" + ex.Message);
            uiModule = IntPtr.Zero;
        }
        if (!IsPointer(uiModule))
        {
            uiModule = memory.Read<IntPtr>(AddOffset(
                framework,
                FrameworkUiModuleOffset75,
                "Framework.UIModule"));
        }
        RequirePointer(uiModule, "UIModule");

        IntPtr agentModule;
        try
        {
            agentModule = plugin.CallVirtualFunction<IntPtr>(
                uiModule,
                GetAgentModuleVtableIndex);
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException(
                "调用 UIModule.GetAgentModule 失败；PostNamazu 跨进程调用不可用。",
                ex);
        }
        RequirePointer(agentModule, "AgentModule");
        ValidateAgentModule(agentModule, uiModule);

        inspectAgent = memory.Read<IntPtr>(
            agentModule + AgentArrayOffset + (InspectAgentId * IntPtr.Size));
        RequirePointer(inspectAgent, "AgentInspect");
        ValidateInspectAgent();

        inventoryManager = scanner.ScanText(
            "48 8D 0D * * * * 81 C2",
            "SpecialAttributeCheck.InventoryManager");
        RequirePointer(inventoryManager, "InventoryManager");
        examineItemsContainer = IntPtr.Zero;
        examineContainerLookupAttempted = false;

        groupManager = scanner.ScanText(
            "33 D2 48 8D 0D * * * * 33 DB",
            "SpecialAttributeCheck.GroupManager");
        RequirePointer(groupManager, "GroupManager");

        var atkStageStatic = scanner.ScanText(
            "48 8B 05 * * * * 4C 8B 40 18 45 8B 40 18",
            "SpecialAttributeCheck.AtkStage");
        var atkStage = memory.Read<IntPtr>(atkStageStatic);
        RequirePointer(atkStage, "AtkStage");
        raptureAtkUnitManager = memory.Read<IntPtr>(AddOffset(
            atkStage,
            AtkStageRaptureUnitManagerOffset,
            "AtkStage.RaptureAtkUnitManager"));
        RequirePointer(raptureAtkUnitManager, "RaptureAtkUnitManager");
    }

    private async Task<SpecialAttributeInspectAttemptResult> TryInspectAsync(
        SpecialAttributePlayer target,
        IntPtr hardTargetAddress,
        string traceLabel,
        bool verbose,
        ICollection<IntPtr> ownedTargetAddresses,
        Func<SpecialAttributePlayer> refreshTarget,
        CancellationToken cancellation)
    {
        var requestStarted = false;
        var inspectStatusAddress = AddOffset(
            inspectAgent,
            InspectStatusOffset,
            "AgentInspect.Status");
        var inspectEntityAddress = AddOffset(
            inspectAgent,
            InspectCurrentEntityOffset,
            "AgentInspect.CurrentEntity");
        try
        {
            var targetToken = await PrepareVerifiedInspectRequestAsync(
                target,
                hardTargetAddress,
                inspectStatusAddress,
                traceLabel,
                verbose,
                ownedTargetAddresses,
                refreshTarget,
                cancellation).ConfigureAwait(false);
            requestStarted = true;
            plugin.DoActionForce("DoTextCommand", "/check " + targetToken);
            Trace(verbose, traceLabel + "：已发送 /check " + targetToken);
            return await WaitForInspectItemsAsync(
                target.EntityId,
                inspectEntityAddress,
                inspectStatusAddress,
                traceLabel,
                verbose,
                cancellation).ConfigureAwait(false);
        }
        finally
        {
            if (requestStarted)
            {
                Trace(verbose, traceLabel + "：开始清理查看窗口");
                CleanupInspectRequest(
                    target.EntityId,
                    inspectEntityAddress,
                    inspectStatusAddress,
                    traceLabel,
                    verbose);
                await Task.Delay(
                    SpecialAttributeInspectPolicy.CloseSettleMilliseconds)
                    .ConfigureAwait(false);
                Trace(verbose, traceLabel + "：清理完成");
            }
        }
    }

    private async Task<string> PrepareVerifiedInspectRequestAsync(
        SpecialAttributePlayer target,
        IntPtr hardTargetAddress,
        IntPtr inspectStatusAddress,
        string traceLabel,
        bool verbose,
        ICollection<IntPtr> ownedTargetAddresses,
        Func<SpecialAttributePlayer> refreshTarget,
        CancellationToken cancellation)
    {
        await EnsureInspectWindowClosedAsync(
            traceLabel,
            verbose,
            cancellation).ConfigureAwait(false);
        RefreshInspectTargetOrThrow(
            target, refreshTarget, traceLabel, verbose);
        PrepareInspectRequest(
            target,
            hardTargetAddress,
            inspectStatusAddress,
            ownedTargetAddresses);
        await Task.Delay(
            SpecialAttributeInspectPolicy.PollDelayMilliseconds,
            cancellation).ConfigureAwait(false);
        RefreshInspectTargetOrThrow(
            target, refreshTarget, traceLabel, verbose);
        return PrepareInspectRequest(
            target,
            hardTargetAddress,
            inspectStatusAddress,
            ownedTargetAddresses);
    }

    private void RefreshInspectTargetOrThrow(
        SpecialAttributePlayer target,
        Func<SpecialAttributePlayer> refreshTarget,
        string traceLabel,
        bool verbose)
    {
        if (refreshTarget == null)
            return;
        var refreshed = refreshTarget();
        if (refreshed == null
            || refreshed.EntityId != target.EntityId
            || !IsPointer(refreshed.Address))
        {
            Trace(verbose, traceLabel + "：目标已不在附近，停止查看");
            throw new SpecialAttributeTargetUnavailableException(
                "目标已离开 20 米范围或已从实体表消失。");
        }

        target.Name = refreshed.Name;
        target.JobId = refreshed.JobId;
        target.JobName = refreshed.JobName;
        target.XPosition = refreshed.XPosition;
        target.YPosition = refreshed.YPosition;
        target.ZPosition = refreshed.ZPosition;
        target.X = refreshed.X;
        target.IsLocal = refreshed.IsLocal;
        target.InParty = refreshed.InParty;
        target.PartyIndex = refreshed.PartyIndex;
        target.TargetId = refreshed.TargetId;
        target.Address = refreshed.Address;
        Trace(verbose, string.Format(
            "{0}：目标仍在 20 米内，实体地址=0x{1:X}",
            traceLabel,
            target.Address.ToInt64()));
    }

    private string PrepareInspectRequest(
        SpecialAttributePlayer target,
        IntPtr hardTargetAddress,
        IntPtr inspectStatusAddress,
        ICollection<IntPtr> ownedTargetAddresses)
    {
        examineItemsContainer = IntPtr.Zero;
        examineContainerLookupAttempted = false;
        memory.Write(inspectStatusAddress, 0u);
        if (target.Address == IntPtr.Zero)
            return "<" + target.PartyIndex + ">";

        RequirePointer(target.Address, "目标实体");
        ownedTargetAddresses.Add(target.Address);
        entityModule.Target(target.Address, true, true);
        var hardTarget = memory.Read<IntPtr>(hardTargetAddress);
        if (hardTarget != target.Address)
            throw new InvalidOperationException("设置查看目标失败，已拒绝读取装备。");
        return "<t>";
    }

    private async Task EnsureInspectWindowClosedAsync(
        string traceLabel,
        bool verbose,
        CancellationToken cancellation)
    {
        Exception closeError = null;
        var lastCloseError = string.Empty;
        var sawAddon = false;
        var timer = SpecialAttributeElapsedTimer.StartNew();
        while (timer.ElapsedMilliseconds
            < SpecialAttributeInspectPolicy.WindowCloseTimeoutMilliseconds)
        {
            cancellation.ThrowIfCancellationRequested();
            var addon = FindCharacterInspectAddon();
            if (addon == IntPtr.Zero)
            {
                Trace(verbose, sawAddon
                    ? traceLabel + "：残留窗口已关闭，耗时=" + timer.ElapsedMilliseconds + "ms"
                    : traceLabel + "：旧窗口=无");
                return;
            }
            if (!sawAddon)
            {
                sawAddon = true;
                Trace(verbose, traceLabel + "：发现残留 CharacterInspect，开始关闭");
            }
            try
            {
                if (!CloseInspectAddon(addon))
                    closeError = new InvalidOperationException("CharacterInspect 拒绝关闭请求。");
            }
            catch (Exception ex)
            {
                closeError = ex;
            }
            var closeMessage = closeError == null ? string.Empty : closeError.Message;
            if (closeMessage.Length != 0 && closeMessage != lastCloseError)
            {
                lastCloseError = closeMessage;
                Trace(verbose, traceLabel + "：关闭残留窗口失败：" + closeMessage);
            }
            await Task.Delay(
                SpecialAttributeInspectPolicy.CloseSettleMilliseconds,
                cancellation).ConfigureAwait(false);
        }
        throw new TimeoutException(
            "旧查看窗口未能在 2 秒内关闭。",
            closeError);
    }

    private async Task<SpecialAttributeInspectAttemptResult> WaitForInspectItemsAsync(
        uint targetId,
        IntPtr inspectEntityAddress,
        IntPtr inspectStatusAddress,
        string traceLabel,
        bool verbose,
        CancellationToken cancellation)
    {
        var lastAttempt = new SpecialAttributeInspectAttemptResult(
            null,
            FormatInspectDiagnostic(targetId, 0, 0, "无", -1, -1, false));
        var timer = SpecialAttributeElapsedTimer.StartNew();
        var lastReported = string.Empty;
        var nextHeartbeat = 0L;
        while (timer.ElapsedMilliseconds
            < SpecialAttributeInspectPolicy.InspectTimeoutMilliseconds)
        {
            cancellation.ThrowIfCancellationRequested();
            lastAttempt = await ReadStableInspectAttemptAsync(
                targetId,
                inspectEntityAddress,
                inspectStatusAddress,
                cancellation).ConfigureAwait(false);
            var elapsed = timer.ElapsedMilliseconds;
            if (lastAttempt.Diagnostic != lastReported || elapsed >= nextHeartbeat)
            {
                lastReported = lastAttempt.Diagnostic;
                nextHeartbeat = elapsed + 2000;
                Trace(verbose, string.Format(
                    "{0}：等待 {1}ms；{2}",
                    traceLabel,
                    elapsed,
                    lastAttempt.Diagnostic));
            }
            if (lastAttempt.Items != null)
            {
                Trace(verbose, string.Format(
                    "{0}：装备数据稳定，耗时={1}ms，槽位={2}",
                    traceLabel,
                    elapsed,
                    lastAttempt.Items.Count));
                return lastAttempt;
            }
            await Task.Delay(
                SpecialAttributeInspectPolicy.PollDelayMilliseconds,
                cancellation).ConfigureAwait(false);
        }
        Trace(verbose, traceLabel + "：读取超时；" + lastAttempt.Diagnostic);
        return lastAttempt;
    }

    private void Trace(bool enabled, string message)
    {
        if (enabled)
            diagnostic("诊断 " + message);
    }

    private async Task<SpecialAttributeInspectAttemptResult> ReadStableInspectAttemptAsync(
        uint targetId,
        IntPtr inspectEntityAddress,
        IntPtr inspectStatusAddress,
        CancellationToken cancellation)
    {
        var currentEntity = memory.Read<uint>(inspectEntityAddress);
        var status = memory.Read<uint>(inspectStatusAddress);
        var inspectAddonOpen = FindCharacterInspectAddon() != IntPtr.Zero;
        string source;
        int examineCount;
        int agentCount;
        ReadPreferredInspectItemIds(
            targetId,
            currentEntity,
            status,
            out source,
            out examineCount,
            out agentCount);
        if (!SpecialAttributeInspectPolicy.CanAcceptInspectSource(
            source, targetId, currentEntity, status, inspectAddonOpen))
        {
            return CreateInspectAttemptResult(
                null, targetId, currentEntity, status, source,
                examineCount, agentCount, inspectAddonOpen);
        }

        await Task.Delay(
            SpecialAttributeInspectPolicy.ReadySettleMilliseconds,
            cancellation).ConfigureAwait(false);
        currentEntity = memory.Read<uint>(inspectEntityAddress);
        status = memory.Read<uint>(inspectStatusAddress);
        inspectAddonOpen = FindCharacterInspectAddon() != IntPtr.Zero;
        string firstSource;
        var first = ReadPreferredInspectItemIds(
            targetId,
            currentEntity,
            status,
            out firstSource,
            out examineCount,
            out agentCount);
        source = firstSource;
        if (!SpecialAttributeInspectPolicy.CanAcceptInspectSource(
            firstSource, targetId, currentEntity, status, inspectAddonOpen))
        {
            return CreateInspectAttemptResult(
                null, targetId, currentEntity, status, source,
                examineCount, agentCount, inspectAddonOpen);
        }

        await Task.Delay(
            SpecialAttributeInspectPolicy.PollDelayMilliseconds,
            cancellation).ConfigureAwait(false);
        return ReadFinalInspectAttempt(
            targetId,
            inspectEntityAddress,
            inspectStatusAddress,
            firstSource,
            first);
    }

    private SpecialAttributeInspectAttemptResult ReadFinalInspectAttempt(
        uint targetId,
        IntPtr inspectEntityAddress,
        IntPtr inspectStatusAddress,
        string firstSource,
        IReadOnlyList<uint> first)
    {
        string secondSource;
        int examineCount;
        int agentCount;
        var currentEntity = memory.Read<uint>(inspectEntityAddress);
        var status = memory.Read<uint>(inspectStatusAddress);
        var inspectAddonOpen = FindCharacterInspectAddon() != IntPtr.Zero;
        var second = ReadPreferredInspectItemIds(
            targetId,
            currentEntity,
            status,
            out secondSource,
            out examineCount,
            out agentCount);
        var items = firstSource == secondSource
            && SpecialAttributeInspectPolicy.IsStableMatch(
                secondSource, targetId, currentEntity, status,
                inspectAddonOpen, first, second)
            ? second.Where(item => item != 0).ToArray()
            : null;
        return CreateInspectAttemptResult(
            items, targetId, currentEntity, status, secondSource,
            examineCount, agentCount, inspectAddonOpen);
    }

    private static SpecialAttributeInspectAttemptResult CreateInspectAttemptResult(
        IReadOnlyList<uint> items,
        uint targetId,
        uint currentEntity,
        uint status,
        string source,
        int examineCount,
        int agentCount,
        bool inspectAddonOpen)
    {
        return new SpecialAttributeInspectAttemptResult(
            items,
            FormatInspectDiagnostic(
                targetId, currentEntity, status, source,
                examineCount, agentCount, inspectAddonOpen));
    }

    private IReadOnlyList<uint> ReadPreferredInspectItemIds(
        uint targetId,
        uint currentEntity,
        uint status,
        out string source,
        out int examineCount,
        out int agentCount)
    {
        var examineItems = TryReadExamineItemIds();
        var agentItems = ReadInspectItemIds();
        examineCount = examineItems == null ? -1 : examineItems.Count(item => item != 0);
        agentCount = agentItems.Count(item => item != 0);
        return SpecialAttributeInspectPolicy.SelectPreferredItems(
            examineItems,
            agentItems,
            SpecialAttributeInspectPolicy.IsAgentInspectReady(
                targetId, currentEntity, status),
            out source);
    }

    private static string FormatInspectDiagnostic(
        uint targetId,
        uint currentEntity,
        uint status,
        string source,
        int examineCount,
        int agentCount,
        bool inspectAddonOpen)
    {
        return string.Format(
            "目标={0:X8} 实际={1:X8} status={2} source={3} Examine={4} Agent={5} Addon={6}",
            targetId,
            currentEntity,
            status,
            source,
            examineCount,
            agentCount,
            inspectAddonOpen ? "开" : "关");
    }

    private uint[] ReadInspectItemIds()
    {
        var result = new uint[InspectSlotCount];
        for (var index = 0; index < InspectSlotCount; index++)
        {
            result[index] = memory.Read<uint>(
                inspectAgent + InspectItemsOffset + (index * InspectItemSize));
        }
        return result;
    }

    private uint[] TryReadExamineItemIds()
    {
        if (!examineContainerLookupAttempted)
        {
            examineItemsContainer = FindInventoryContainer(ExamineItemsType);
            examineContainerLookupAttempted = true;
        }
        if (examineItemsContainer == IntPtr.Zero)
            return null;
        return TryReadInventoryContainerSnapshot(examineItemsContainer);
    }

    private IntPtr FindCharacterInspectAddon()
    {
        var list = AddOffset(
            raptureAtkUnitManager,
            AllLoadedUnitsListOffset,
            "RaptureAtkUnitManager.AllLoadedUnitsList");
        var count = memory.Read<ushort>(AddOffset(
            list,
            AtkUnitListCountOffset,
            "AtkUnitList.Count"));
        if (count > MaxLoadedAtkUnits)
            throw new InvalidOperationException("AtkUnitList 数量无效；当前布局可能已过期。");

        for (var index = 0; index < count; index++)
        {
            var addon = memory.Read<IntPtr>(AddOffset(
                list,
                AtkUnitListEntriesOffset + (index * IntPtr.Size),
                "AtkUnitList.Entry[" + index + "]"));
            if (addon == IntPtr.Zero)
                continue;
            var name = ReadUtf8(AddOffset(
                addon,
                AtkUnitNameOffset,
                "AtkUnitBase.Name"), AtkUnitNameLength);
            if (string.Equals(name, CharacterInspectAddonName, StringComparison.Ordinal))
                return addon;
        }
        return IntPtr.Zero;
    }

    private bool CloseInspectAddon(IntPtr addon)
    {
        RequirePointer(addon, "CharacterInspect");
        RequirePointer(memory.Read<IntPtr>(addon), "CharacterInspect vtable");
        return plugin.CallVirtualFunction<byte>(
            addon,
            AtkUnitCloseVtableIndex,
            true) != 0;
    }

    private IntPtr FindInventoryContainer(int expectedType)
    {
        var containers = memory.Read<IntPtr>(AddOffset(
            inventoryManager,
            InventoryContainersOffset,
            "InventoryManager.Inventories"));
        RequirePointer(containers, "InventoryManager.Inventories");
        for (var index = 0; index < MaxInventoryContainers; index++)
        {
            var container = AddOffset(
                containers,
                index * InventoryContainerSize,
                "InventoryContainer[" + index + "]");
            try
            {
                if (memory.Read<int>(AddOffset(
                    container,
                    InventoryTypeOffset,
                    "InventoryContainer.Type")) == expectedType)
                {
                    return container;
                }
            }
            catch (Exception ex)
            {
                throw new InvalidOperationException(
                    "扫描 InventoryContainer 失败，索引=" + index + "。",
                    ex);
            }
        }
        return IntPtr.Zero;
    }

    private IReadOnlyList<uint> ReadInventoryContainer(IntPtr container)
    {
        var snapshot = TryReadInventoryContainerSnapshot(container);
        if (snapshot == null)
            throw new InvalidOperationException("EquippedItems 容器未加载或槽位数无效。");
        return snapshot.Where(item => item != 0).ToArray();
    }

    private uint[] TryReadInventoryContainerSnapshot(IntPtr container)
    {
        var loaded = memory.Read<byte>(container + InventoryLoadedOffset) != 0;
        var size = memory.Read<int>(container + InventorySizeOffset);
        if (!loaded)
            return null;
        if (size <= 0 || size > 64)
            throw new InvalidOperationException("InventoryContainer 槽位数无效：" + size);
        var items = memory.Read<IntPtr>(container + InventoryItemsOffset);
        RequirePointer(items, "InventoryContainer.Items");
        var result = new uint[size];
        for (var index = 0; index < size; index++)
        {
            result[index] = memory.Read<uint>(
                items + (index * InventoryItemSize) + InventoryItemIdOffset);
        }
        return result;
    }

    private void ValidateAgentModule(IntPtr agentModule, IntPtr uiModule)
    {
        var vtable = memory.Read<IntPtr>(agentModule);
        RequirePointer(vtable, "AgentModule vtable");
        var ownerUiModule = memory.Read<IntPtr>(AddOffset(
            agentModule,
            AgentModuleUiModuleOffset,
            "AgentModule.UIModule"));
        if (ownerUiModule != uiModule)
            throw new InvalidOperationException("AgentModule 所属 UIModule 校验失败；当前布局可能已过期。");
    }

    private void ValidateInspectAgent()
    {
        var status = memory.Read<uint>(inspectAgent + InspectStatusOffset);
        if (status > 4)
            throw new InvalidOperationException("AgentInspect 状态字段验证失败；当前布局可能已过期。");
        var vtable = memory.Read<IntPtr>(inspectAgent);
        RequirePointer(vtable, "AgentInspect vtable");
    }

    private int ReadSupportJobStacks(IntPtr partyMember)
    {
        var result = 0;
        for (var index = 0; index < StatusCount; index++)
        {
            var status = partyMember + StatusArrayOffset + (index * StatusSize);
            if (memory.Read<ushort>(status) == SpecialAttributeData.SupportJobMasterStatusId)
                result += memory.Read<ushort>(status + 2);
        }
        return result;
    }

    private string ReadUtf8(IntPtr address, int maxLength)
    {
        var bytes = memory.ReadBytes(address, maxLength);
        var length = Array.IndexOf(bytes, (byte)0);
        if (length < 0)
            length = bytes.Length;
        return Encoding.UTF8.GetString(bytes, 0, length);
    }

    private void CleanupInspectRequest(
        uint targetId,
        IntPtr inspectEntityAddress,
        IntPtr inspectStatusAddress,
        string traceLabel,
        bool verbose)
    {
        var currentEntity = 0u;
        var status = 0u;
        var stateRead = false;
        var closeSucceeded = true;
        try
        {
            currentEntity = memory.Read<uint>(inspectEntityAddress);
            status = memory.Read<uint>(inspectStatusAddress);
            stateRead = true;
        }
        catch (Exception ex)
        {
            var message = "读取 AgentInspect 清理状态失败：" + ex.Message;
            log(message);
            Trace(verbose, traceLabel + "：" + message);
        }

        if (stateRead && !SpecialAttributeInspectPolicy.OwnsInspectRequest(
            targetId, currentEntity))
        {
            Trace(verbose, string.Format(
                "{0}：跳过清理，Agent 已切换到 {1:X8}/status={2}",
                traceLabel,
                currentEntity,
                status));
            return;
        }

        closeSucceeded = TryCloseInspectAddonForCleanup(
            currentEntity,
            status,
            stateRead,
            inspectEntityAddress,
            inspectStatusAddress,
            traceLabel,
            verbose);
        if (!stateRead || !closeSucceeded)
            return;
        ResetInspectStatusIfUnchanged(
            currentEntity,
            status,
            inspectEntityAddress,
            inspectStatusAddress,
            traceLabel,
            verbose);
    }

    private bool TryCloseInspectAddonForCleanup(
        uint currentEntity,
        uint status,
        bool stateRead,
        IntPtr inspectEntityAddress,
        IntPtr inspectStatusAddress,
        string traceLabel,
        bool verbose)
    {
        try
        {
            var addon = FindCharacterInspectAddon();
            if (addon == IntPtr.Zero)
                return true;
            if (stateRead
                && (memory.Read<uint>(inspectEntityAddress) != currentEntity
                    || memory.Read<uint>(inspectStatusAddress) != status))
            {
                Trace(verbose, traceLabel + "：清理前 Agent 状态已变化，保留当前窗口");
                return false;
            }
            if (CloseInspectAddon(addon))
                return true;
            const string refused = "关闭查看窗口失败：CharacterInspect 拒绝关闭请求。";
            log(refused);
            Trace(verbose, traceLabel + "：" + refused);
            return false;
        }
        catch (Exception ex)
        {
            var message = "关闭查看窗口失败：" + ex.Message;
            log(message);
            Trace(verbose, traceLabel + "：" + message);
            return false;
        }
    }

    private void ResetInspectStatusIfUnchanged(
        uint expectedEntity,
        uint expectedStatus,
        IntPtr inspectEntityAddress,
        IntPtr inspectStatusAddress,
        string traceLabel,
        bool verbose)
    {
        try
        {
            var latestEntity = memory.Read<uint>(inspectEntityAddress);
            var latestStatus = memory.Read<uint>(inspectStatusAddress);
            if (latestEntity == expectedEntity && latestStatus == expectedStatus)
                memory.Write(inspectStatusAddress, 0u);
            else
                Trace(verbose, traceLabel + "：Agent 状态已变化，跳过 status 重置");
        }
        catch (Exception ex)
        {
            var message = "重置 AgentInspect 状态失败：" + ex.Message;
            log(message);
            Trace(verbose, traceLabel + "：" + message);
        }
    }

    private Exception TryRestoreTarget(
        IntPtr address,
        ICollection<IntPtr> ownedValues,
        IntPtr originalValue,
        string targetKind)
    {
        if (ownedValues == null || ownedValues.Count == 0)
            return null;
        try
        {
            var currentValue = memory.Read<IntPtr>(address);
            if (!ownedValues.Contains(currentValue))
            {
                log("检测期间" + targetKind + "已变化，跳过恢复以保留当前目标。");
                return null;
            }
            memory.Write(address, originalValue);
            return null;
        }
        catch (Exception ex)
        {
            log("恢复玩家" + targetKind + "失败：" + ex.Message);
            return ex;
        }
    }

    private static void AddError(ICollection<Exception> errors, Exception error)
    {
        if (error != null)
            errors.Add(error);
    }

    private static IntPtr AddOffset(IntPtr pointer, int offset, string name)
    {
        RequirePointer(pointer, name + " base");
        try
        {
            var address = new IntPtr(checked(pointer.ToInt64() + offset));
            RequirePointer(address, name);
            return address;
        }
        catch (OverflowException ex)
        {
            throw new InvalidOperationException(name + " 地址溢出；当前布局可能已过期。", ex);
        }
    }

    private static bool IsPointer(IntPtr pointer)
    {
        var value = pointer.ToInt64();
        return value >= 0x10000 && value <= 0x00007FFFFFFFFFFF;
    }

    private static void RequirePointer(IntPtr pointer, string name)
    {
        if (!IsPointer(pointer))
            throw new InvalidOperationException(name + " 指针无效；当前签名或布局可能已过期。");
    }
}

internal sealed class SpecialAttributeMemory
{
    private readonly GreyMagicExternalProcessMemory primary;

    public SpecialAttributeMemory(GreyMagicExternalProcessMemory primaryMemory)
    {
        if (primaryMemory == null)
            throw new ArgumentNullException("primaryMemory");
        primary = primaryMemory;
    }

    public T Read<T>(IntPtr address) where T : struct
    {
        ValidateAddress(address, SizeOfValue<T>());
        try
        {
            return primary.Read<T>(address);
        }
        catch (Exception primaryError)
        {
            try
            {
                return Triggernometry.Utilities.Memory.Read<T>(
                    Triggernometry.Utilities.Memory.XivProcHandle,
                    address);
            }
            catch (Exception fallbackError)
            {
                throw new AggregateException("两条内存读取路径均失败。", primaryError, fallbackError);
            }
        }
    }

    public byte[] ReadBytes(IntPtr address, int count)
    {
        ValidateAddress(address, count);
        try
        {
            return primary.ReadBytes(address, count);
        }
        catch (Exception primaryError)
        {
            try
            {
                return Triggernometry.Utilities.Memory.ReadBytes(
                    Triggernometry.Utilities.Memory.XivProcHandle,
                    address,
                    (uint)count);
            }
            catch (Exception fallbackError)
            {
                throw new AggregateException("两条内存读取路径均失败。", primaryError, fallbackError);
            }
        }
    }

    public void Write<T>(IntPtr address, T value) where T : struct
    {
        ValidateAddress(address, SizeOfValue<T>());
        try
        {
            primary.Write(address, value);
        }
        catch (Exception primaryError)
        {
            try
            {
                Triggernometry.Utilities.Memory.Write(
                    Triggernometry.Utilities.Memory.XivProcHandle,
                    address,
                    value);
            }
            catch (Exception fallbackError)
            {
                throw new AggregateException("两条内存写入路径均失败。", primaryError, fallbackError);
            }
        }
    }

    public static int SizeOfValue<T>() where T : struct
    {
        var type = typeof(T);
        if (type == typeof(byte))
            return 1;
        if (type == typeof(ushort))
            return 2;
        if (type == typeof(int)
            || type == typeof(uint)
            || type == typeof(float))
            return 4;
        if (type == typeof(IntPtr))
            return IntPtr.Size;
        throw new NotSupportedException(
            "不支持的内存值类型：" + type.FullName);
    }

    private static void ValidateAddress(IntPtr address, int size)
    {
        if (size <= 0)
            throw new ArgumentOutOfRangeException("size");
        var start = address.ToInt64();
        long end;
        try
        {
            end = checked(start + size - 1L);
        }
        catch (OverflowException ex)
        {
            throw new InvalidOperationException("内存访问地址溢出。", ex);
        }
        if (start < 0x10000 || end > 0x00007FFFFFFFFFFF)
            throw new InvalidOperationException("内存访问地址无效；当前签名或布局可能已过期。");
    }
}

